use std::net::{ Ipv4Addr };//, IpAddr };
use crate::netlib::*;

use std::env;

const SSH_DATA: &str = "5353482d322e302d4f70656e5353485f392e3470312044656269616e2d310d0a";
const SSH_DATA2: &str = "";

const SSH_DATA3: &str = "";

pub fn keyscan (ip: Ipv4Addr) -> Result<(u64, sockaddr, Packet), LinuxError> {
    let tmp_pkt = Packet { protocol: IPPROTO_TCP, ip: ip, ttl: 64, port: 22, data: from_hex(SSH_DATA) };
    Ok(sendTCPSequence(tmp_pkt, vec![ SSH_DATA2, SSH_DATA3 ]))?
}

pub fn parseKeyscan (data: &Vec<u8>) -> Vec<u8> {
    //let ssh_rsa  73 73 68 2d 72 73 61
    debug!("ssh parseKeyscan {data:x?}");
    //debug!("ssh ssh_rsa as bytes {:x?}", "ssh-rsa".as_bytes());
    let index = data.windows(7).position(|window| window == "ssh-rsa".as_bytes()).unwrap(); // ssh-rsa

    let key_length = u32::from_be_bytes(data[index - 8..index - 4].try_into().unwrap());

    (&data[index..index + key_length as usize]).to_vec()
}
